{
  "primary_meaning": "A visual reminder to remember and obey all of God's commandments and to live a holy life set apart from sin",
  "primary_basis": [
    "Numbers 15:37-41",
    "Deuteronomy 22:12"
  ],
  "alternatives": [
    {
      "meaning": "The fringe or hem of Jesus' garment as a source of healing power and messianic authority, fulfilled when the woman with the issue of blood touched it",
      "basis": [
        "Matthew 9:20-22",
        "Matthew 14:36",
        "Mark 6:56",
        "Luke 8:43-48"
      ],
      "prominence": "common"
    },
    {
      "meaning": "A symbol of the covenant people of God or Jewish identity under the Mosaic Law, now fulfilled or set aside in Christ",
      "basis": [
        "Numbers 15:37-41",
        "Galatians 3:23-25",
        "Colossians 2:16-17"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "The blue thread (tekhelet) specifically representing heaven, divinity, or the throne of God",
      "basis": [
        "Numbers 15:38-39",
        "Exodus 24:10",
        "Ezekiel 1:26"
      ],
      "prominence": "rare"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "The explicit purpose statement in Numbers 15 supplies a clear primary meaning that is consistently recognized in Christian biblical interpretation of the Old Testament command; secondary Christian applications center on New Testament references to Jesus' tassels but do not displace the original stated symbolism."
}
